import { execSync } from 'child_process';
import fs from 'fs';
const W='';
const FILES={"includes/class-weight-filter.php": "", "includes/class-product-calc.php": "", "assets/product-calc.js": ""};
const TOKG=process.env.GH_TOKEN, REPO=process.env.GH_REPO||'raimis079-creator/petshop-bridge';
const U=process.env.WP_USER||'', P=(process.env.WP_APP_PASS||'').replace(/\s+/g,'');
const AUTH='-u "'+U+':'+P+'"';
function wj(m,path,body){fs.writeFileSync('/tmp/wb.json', JSON.stringify(body));
  return execSync('curl -sk --max-time 150 '+AUTH+' -X '+m+' -H "Content-Type: application/json" --data-binary @/tmp/wb.json "https://dev.avesa.lt/wp-json/'+path+'"',{maxBuffer:50e6,timeout:170000}).toString();}
function putB64(name,b64){const u='https://api.github.com/repos/'+REPO+'/contents/screenshots/'+name;let s='';
 for(let i=0;i<6;i++){try{const j=JSON.parse(execSync('curl -s -H "Authorization: Bearer '+TOKG+'" "'+u+'?n='+Math.random()+'"',{maxBuffer:50e6}).toString());if(j.sha)s=j.sha;}catch(e){}
  fs.writeFileSync('/tmp/pj.json',JSON.stringify({message:'r',content:b64,...(s?{sha:s}:{})}));
  const c=execSync('curl -s -o /dev/null -w "%{http_code}" -X PUT -H "Authorization: Bearer '+TOKG+'" -d @/tmp/pj.json "'+u+'"',{maxBuffer:50e6}).toString().trim();
  if(c==='200'||c==='201')return c; execSync('sleep 3');}return 'fail';}
const o={marker:'S305'}; let sid=null;
try{
  let mk=null;
  for(let a=0;a<3;a++){ try{ mk=wj('POST','code-snippets/v1/snippets',{name:'S305 '+Date.now(),code:Buffer.from(W,'base64').toString('utf8'),scope:'front-end',active:true,priority:5});
    if(mk && mk.indexOf('"id"')>=0) break; }catch(e){} execSync('sleep 8'); }
  try{sid=JSON.parse(mk).id;}catch(e){o.mk=String(mk).slice(0,120);}
  execSync('sleep 5');
  fs.writeFileSync('/tmp/payload.json', JSON.stringify({files:FILES}));
  for(let a=0;a<3;a++){ try{const r=execSync('curl -sk --max-time 120 -X POST -H "Content-Type: application/json" --data-binary @/tmp/payload.json "https://dev.avesa.lt/?ps_dep218=Dp218x"',{maxBuffer:20e6,timeout:140000}).toString();
    const j=r.slice(r.indexOf('{'),r.lastIndexOf('}')+1); o.write=j; if(j.includes('weight-filter')&&j.includes('product-calc.js')) break; }catch(e){o.write='ERR '+a;} execSync('sleep 5'); }
  if(sid!==null){ try{execSync('curl -sk --max-time 60 '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid+'"');}catch(e){} sid=null; }

  const base='https://dev.avesa.lt/kategorija/sunims/maistas-sunims/sausas-maistas-sunims/';
  const prod='https://dev.avesa.lt/product/exclusion-hypoallergenic-sausas-sunu-maistas-su-arkliena-ir-bulvemis-m-l-12-kg/';
  const g=(u)=>execSync('curl -skL --max-time 70 "'+u+'"',{maxBuffer:20e6,timeout:85000}).toString();
  const probe=(tag)=>{
    const h1=g(base), h2=g(base+'?ps_weight=13&ps_species=dog'), h3=g(prod);
    o[tag]={forma:(h1.match(/<form class="ps-wask"/g)||[]).length,
            badge:(h2.match(/<div class="ps-cb">/g)||[]).length,
            filtras:(h2.match(/<div class="ps-wfilter">/g)||[]).length,
            listurl:(h3.match(/data-listurl="([^"]*)"/)||[])[1]||'',
            calc_widget:h3.indexOf('id="ps-calc"')>=0};
  };
  // 1. isjungta (default '0')
  const off='<?php add_action("wp_loaded",function(){ if(!isset($_GET["ps_fl"])) return; '
   +'if($_GET["ps_fl"]==="off") delete_option("petshop_calc_category_enabled"); '
   +'if($_GET["ps_fl"]==="on") update_option("petshop_calc_category_enabled","1"); '
   +'header("Content-Type: application/json"); echo json_encode(array("v"=>get_option("petshop_calc_category_enabled","0"),"enabled"=>Petshop_Weight_Filter::enabled())); exit; });';
  let m2=null;
  for(let a=0;a<3;a++){ try{ m2=wj('POST','code-snippets/v1/snippets',{name:'FL '+Date.now(),code:off,scope:'front-end',active:true,priority:5});
    if(m2 && m2.indexOf('"id"')>=0) break; }catch(e){} execSync('sleep 8'); }
  let sid2=null; try{sid2=JSON.parse(m2).id;}catch(e){}
  execSync('sleep 5');
  try{ o.busena_off=JSON.parse(g('https://dev.avesa.lt/?ps_fl=off').match(/\{[\s\S]*\}/)[0]); }catch(e){}
  probe('ISJUNGTA');
  try{ o.busena_on=JSON.parse(g('https://dev.avesa.lt/?ps_fl=on').match(/\{[\s\S]*\}/)[0]); }catch(e){}
  probe('IJUNGTA');
  if(sid2!==null){ try{execSync('curl -sk --max-time 60 '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid2+'"');}catch(e){} }
}catch(e){ o.err=String(e).slice(0,250); }
try{ if(sid!=null) execSync('curl -sk --max-time 60 '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid+'"'); }catch(e){}
putB64('s305.json', Buffer.from(JSON.stringify(o)).toString('base64'));
console.log('done');
